    fun status(status: String): ImageVector = when (status) {
        "in_progress" -> InProgress
        "completed" -> Completed
        "cancelled" -> Cancelled
        else -> Todo
    }

    fun priority(priority: String): ImageVector = when (priority) {
        "critical" -> PriorityCritical
        "high" -> PriorityHigh
        "low" -> PriorityLow
        "trivial" -> PriorityTrivial
        else -> PriorityMedium
    }
